-- Batch: 46 D2C & consumer brands from imported sheet (deduped, Sep 2026).
-- Run once in the SQL Editor. Safe to re-run: inserts skip existing slugs.

on conflict (slug) do nothing;

-- Unify sector labels: existing Consumer/D2C startups -> 'D2C & Consumer'.
update public.listings set sector = 'D2C & Consumer'
  where type = 'startup' and sector in ('Consumer', 'D2C');
